"""R70 S8: B21+B22 blind predictions. Writes only this batch's ids, with assertions."""
import json, pathlib
BASE = pathlib.Path('/home/hatch/workspace/divination/benchmark/phase3/runs/round70')
OUT = BASE / 'predictions'
OUT.mkdir(parents=True, exist_ok=True)
BATCHES = json.loads((BASE / 'batches.json').read_text(encoding='utf-8'))

def trig(cm=False, ru=False, di=False, reason=''):
    return {'changed_main': cm, 'reserve_used': ru, 'disputed': di, 'reason': reason}

def write_batch(batch_id, entries):
    ids = BATCHES[batch_id]
    assert set(entries.keys()) == set(ids), (batch_id, set(ids) ^ set(entries.keys()))
    assert len(entries) == len(ids) == 20
    for cid in ids:
        e = entries[cid]
        assert set(e.keys()) == {'case_id','prediction_text','basis','confidence','trigger'}, cid
        assert e['case_id'] == cid
        assert isinstance(e['confidence'], float) and 0.0 <= e['confidence'] <= 1.0, cid
        t = e['trigger']
        assert set(t.keys()) == {'changed_main','reserve_used','disputed','reason'}, cid
        assert all(isinstance(t[k], bool) for k in ('changed_main','reserve_used','disputed')), cid
        assert isinstance(t['reason'], str), cid
        (OUT / f'{cid}.json').write_text(json.dumps(e, ensure_ascii=False, indent=1), encoding='utf-8')
    print(batch_id, 'written', len(ids))

