B21['YM-008'] = ly('YM-008','方向：考秩不利（单一终局：不利）。具体断语：官鬼巳火持世而逢亥月冲破，官位之象月破无力；父母未土两现而休囚，考核文书凭据不占优，等第落于下等或有降级之忧。应期双层：窗口为日档一旬内，主坐标巳日（世官逢值实破之日，评定见分晓）。置信：中高。','liuyao\n体系：六爻纳甲，占考秩以官鬼为用神、父母为等第凭据。盘面：亥建甲子旬丙寅日，空戌亥，静卦；用神官鬼巳火二爻持世，亥月冲破、虽得寅日木生而破象在先；子孙亥水四爻旬空；父母未土上爻与初爻两现，亥月休囚、寅日木克。动化方向：静卦无动化，记无动化；反转条件：无动爻，无从成立。破象过表：巳火得日生为有根待实之破，只断评定不利、不直断罢黜（量级据此收束）。对象对齐：待考秩之官本人—官鬼巳火世—应验落其本人等第，同一。应期三步：日档；冲实取亥冲巳（已破不作冲起），填实取巳日实破，逢值同为巳日；填实与逢值同点巳，取巳，舍冲实（破非冲起）。对表：考秩门类对表无此门类，明写无表。R61二路复推：初推填实巳，复推逢值巳，二路同点，保留。',0.65)
B21['YM-009'] = ly('YM-009','方向：摇会可得（单一终局：得）。具体断语：妻财午火持世，子孙寅木初爻临甲寅日建、为财之原神临日生财，会银可到手；兄弟亥水五爻静而不动，劫财之手未伸。应期双层：窗口为日档一旬内，主坐标午日（世财逢值之日得会）。置信：中。','liuyao\n体系：六爻纳甲，占会以妻财为用神。盘面：辰建甲寅旬甲寅日，空子丑，静卦地水师；用神妻财午火三爻持世，辰月泄气中平而得寅日木生；原神子孙寅木初爻临日建，生财有力；忌神兄弟亥水五爻静，辰月入墓不劫。动化方向：静卦无动化；反转条件：无动爻不成立。对象对齐：占会者本人—妻财午火世—应验落占会者本人得会，同一。应期三步：日档；冲实无空破闸门，填实无候选，逢值取午日世财值日；取午，余二路无候选已注明。对表求财门：世动逢合一路不合（世静），首选财入墓一路指劫期非得财期，不取，注明查表取舍。R61二路复推：初推逢值午，复推冲世取子日异点，世静无据冲动，裁午保留。粒度核：得会金额无盘面指针，不报数量。',0.60)
B21['YM-010'] = ly('YM-010','方向：即产且顺产（单一终局：产）。具体断语：子孙亥水旬空而逢己巳日冲空则实，产兆已动；兄弟申金五爻动而生子孙，原神发动催生，母子平安。应期双层：窗口为日档三日内，主坐标巳日（占日当日，冲空实空而产）。置信：中高。','liuyao\n体系：六爻纳甲，占临产以子孙为用神。盘面：午建甲子旬己巳日，空戌亥；用神子孙亥水三爻旬空，午月休囚而逢巳日冲空；原神兄弟申金五爻动生子孙，化父母未土；世爻父母丑土初爻为母体之象。动化方向：申金化未土为化泄，所化未土克水有限，申金本爻生子孙之力在动中成立；方向定性：原神动生用为吉向；反转条件：源绝三征不成立。对象对齐：临产妇人—子孙亥水（胎儿）—产应落在妇人分娩、胎儿落地，逐名复述为妇人产子，同一事体。应期三步：日档；冲实取巳冲亥空，填实取亥日，逢值取亥日；对表产期门首选即空者冲空实空之日，取巳，舍填实逢值亥（迟一日，非首选）。门类对表：产期门已查，首选机制取中。R61二路复推：初推冲空巳，复推填实亥异点，对表首选与闸门释放同指巳，裁巳保留单点。',0.70)
B21['YM-012'] = ly('YM-012','方向：子将归（单一终局：归）。具体断语：子孙酉金五爻持世、临酉月建而旺，行人自身有气；初爻妻财子水临甲子日动而化兄弟丑土，路资已动、归程在途。应期双层：窗口为日档一旬内，主坐标卯日（冲动旺静之子孙酉金，逢冲而归）。置信：中高。','liuyao\n体系：六爻纳甲，卜子归期以子孙为行人用神。盘面：酉建甲子旬甲子日，空戌亥；用神子孙酉金五爻持世临月建，旺相静守；妻财子水初爻临日动化兄弟丑土，子丑相合主路途牵绊少许。动化方向：子水化丑土为化合向；方向定性：用神旺静，动化只涉路资不涉用神本身；反转条件：不成立。行人类复述：归否与归期主语均为未归之子本人，同一。应期三步：日档；冲实取卯冲酉，填实无空，逢值取酉日；对表行人门静而旺者逢冲之例与三步同向，取卯冲，舍逢值酉（值日人未必动身）。门类对表：行人门已查。R61二路复推：初推冲实卯，复推逢值酉异点，旺静逢冲为行人正法，裁卯保留。',0.68)
B21['YM-013'] = ly('YM-013','方向：妻病凶险、终局不愈（单一终局：不愈）。具体断语：近段妻财子水月破临绝、动而化巳，病势急重；远段原神申金伏藏虽得巳日合起，救力迟而弱，不足以挽月破之用神，终局偏凶。应期双层：窗口为日档一旬内，主坐标子日（用神逢值而破绝交集，危期见分晓）。置信：中。','liuyao\n体系：六爻纳甲，卜妻病以妻财为用神。盘面：午建甲子旬己巳日，空戌亥；用神妻财子水两现，取应爻五爻子水为主用：午月冲破、巳日临绝、动化父母巳火；初爻子水同受月破。原神子孙申金不现，伏于五爻之下，巳日合申有起意而月内金囚。官鬼寅木世爻与上爻为病象，寅午半合火势助病。动化方向：子水化巳火为化神与本爻相克绝之向；方向定性：用神动化入绝地为凶向；反转条件：化绝且无生扶一路——子水月破、日绝、原神伏而未动，三无大体成立，维持凶定性。原神存续：申金伏而得日合，判源减未绝，故只断终局不愈、不直断死期（量级收束）。对象对齐：所问对象妻—用神妻财子水—应验对象妻本人，同一；病占复述主语逐条为妻。应期三步：日档；冲实取巳冲亥（非用神），填实取子日实破，逢值同子日；取子，舍冲实（不对用神）。对表疾病门：月破而旺者实破愈——本用神破而绝不旺，不合愈条，反面成立，注明。R61二路复推：初推填实子，复推逢值子，二路同点保留。病位：依据链不全，不报病位。',0.60)
B21['YM-014'] = ly('YM-014','方向：有火惊而无大灾（单一终局：不成大灾）。具体断语：官鬼午火四爻临戊午日旺动，火险之兆近在咫尺，宅中见明火惊扰或小处起火；午火动化父母未土，火泄入土、午未相合收火，终被扑止，不至焚宅。应期双层：窗口为日档三日内，主坐标未日（化神值日、火泄合收之日险情落地消解）。置信：中。','liuyao\n体系：六爻纳甲，占家宅火灾以官鬼为祸患用神、父母为宅体。盘面：未建甲寅旬戊午日，空子丑；用神官鬼午火四爻临日旺动，化父母未土回头泄合；世爻父母戌土上爻为宅，戌午半合而未土月建护宅；子孙子水初爻旬空，制火之力待出空。动化方向：午火化未土为化泄化合；方向定性：祸神动而化泄，险势自收，吉向定性（就宅体安全言）；反转条件：不成立。对象对齐：所问对象家宅—官鬼午火为火患、父母戌土为宅体—应验落在家宅本身（非人对象），同一，不回收到宅主身上。应期三步：日档；冲实取丑冲未（化神），填实取子日出空（子孙制火），逢值取未日化神值；取未为险情见底之点，舍填实子（制火在后段）、舍冲实丑（冲化神反破合）。对表：家宅火灾对表无此门类，明写无表。R61二路复推：初推逢值未，复推填实子异点，化泄收火一路直指未，裁未保留。',0.58)
B21['YM-015'] = ly('YM-015','方向：功名迟得（单一终局：得而迟）。具体断语：父母戌土四爻临甲戌日、得巳月生而动，主功名文书有动；动化兄弟酉金子孙之亲且酉逢甲戌旬空，今科声气泄于空，须待酉字出空值岁方成乡举。应期双层：窗口为年档，主坐标酉年（化神酉金逢值出空之年）。置信：中。','liuyao\n体系：六爻纳甲，占功名以父母为用神、官鬼为禄位。盘面：壬午年巳建甲戌旬甲戌日，空申酉；用神父母戌土四爻临日得月生而动，化兄弟酉金旬空；官鬼巳火二爻应位临月建；子孙子水五爻持世静而囚，克官之力有限。动化方向：戌土化酉金为化泄且化空；方向定性：用神本气旺动为吉底，化空只压应期不翻方向；反转条件：化空无生扶一路部分成立（用神得日月生扶，不合三无），只降格为迟得，不反向断终局。对象对齐：占功名者本人—父母戌土—应验落其本人功名，同一。应期三步：年档（乡举以年科为尺度）；冲实取辰冲戌，填实取酉年填空，逢值取戌年；对表功名发案门空者待冲开填实，化空之神以填实为正，取酉年，舍冲实辰年（冲用神本爻非化神）、舍逢值戌年（本爻值而化空未解）。门类对表：功名门已查旁参。R61二路复推：初推填实酉年，复推冲开辰年异点，尺度同为年档，填实对化空更对位，裁酉年保留。',0.55)
B21['YM-017'] = ly('YM-017','方向：访友可遇（单一终局：遇）。具体断语：五爻发动、独静者为五爻之邻位应爻兄弟申金——众动之中独静之应爻即友人之位，静而逢值则遇。应期双层：窗口为日档一旬内，主坐标申日（独静应爻申金逢值之日遇友）。置信：中。','liuyao\n体系：六爻纳甲，占访友以应爻为友人用神。盘面：未建甲辰旬丙午日，空寅卯；五爻动一爻静：应爻兄弟申金五爻独静，其余父母戌、官鬼午、兄弟申（三爻）、官鬼午世、父母辰皆动。独静章取独静之爻为应机，应爻申金未月囚、午日克，静守待值。动化方向：多爻动化驳杂（辰化巳、午化卯空、申化丑、午化申、戌化子），与用神应爻无直接动化，记动化方向不涉用神；反转条件：不成立。对象对齐：访友者—应爻兄弟申金（友人）—遇应落在友人本人，同一。应期三步：日档；冲实取寅冲申（寅旬空，冲力虚），填实无空，逢值取申日；独静逢值正法，取申，舍冲实寅（空冲不实）。对表：访友门类对表无此门类，明写无表。R61二路复推：初推逢值申，复推冲实寅异点，寅空一路自弱，裁申保留。',0.60,trig(False,False,True,'本例五爻动一爻静，独静之爻定位与应爻取用有两读可能，disputed 记 true 并在 basis 留痕；主断未改取、无备用用神启用。'))
B21['YM-018'] = ly('YM-018','方向：子将归（单一终局：归）。具体断语：子孙酉金五爻持世独静，世即行人之根，静而逢值则人至；余爻五动主路途已在变动之中，归讯先到、人随后至。应期双层：窗口为日档一旬内，主坐标酉日（独静世爻子孙酉金逢值之日归至）。置信：中。','liuyao\n体系：六爻纳甲，占子归以子孙为行人用神。盘面：巳建甲子旬乙丑日，空戌亥；用神子孙酉金五爻持世独静，巳月金处长生、丑日土生；父母巳火、兄弟未土、兄弟丑土、官鬼卯木、父母巳火五爻皆动，路途动象纷然。动化方向：用神静无动化，余爻动化（巳化辰、卯化午、丑化申、未化酉、巳化未）中未土化酉金即化出用神同支，为归气渐集之旁证；方向定性：以独静世用为主断；反转条件：不成立。行人类复述：归否与归期主语均为未归之子本人，同一。应期三步：日档；冲实取卯冲酉，填实无空，逢值取酉日；独静取逢值，取酉，舍冲实卯（冲世反主惊动）。对表行人门：化退归等条不合本盘（用神静），注明按独静法取点。对表已查。R61二路复推：初推逢值酉，复推冲实卯异点，世静逢值较冲世稳，裁酉保留。',0.58,trig(False,False,True,'本例五爻动一爻静，独静世爻取用与余爻动化旁证之间有读法分歧，disputed 记 true 并留痕；主断未改取、无备用用神启用。'))
write_batch('B21', B21)
print('B21 done')

B22 = {}
B22['YM-019'] = ly('YM-019','方向：此婚难成（单一终局：不成）。具体断语：本卦兑为六冲、世应父母未丑相冲，两家意气先冲；妻财卯木二爻午月逢破、生世之情薄；子孙亥水四爻动化兄弟申金回头生，阻力方生，纵变卦成节之合象，也只是礼数往来，终局议散。应期双层：窗口为月档一月内，主坐标卯日（用神妻财逢值而破，议散见分晓）。置信：中。','liuyao\n体系：六爻纳甲，占婚以妻财为用神（占者性别卡面未载，按财为配偶位取用并注明）、世应为两家。盘面：午建甲戌旬丙子日，空申酉；用神妻财卯木二爻，午月木泄、卯午相破；世父母未土上爻、应父母丑土三爻，未丑相冲；子孙亥水四爻动化兄弟申金，申金回头生亥水，子孙旺动克官、主阻隔。动化方向：亥水化申金为化回头生；方向定性：动者为阻神子孙，其回头生只壮阻力，不涉用神吉向；反转条件：不成立。婚占类别读法：世应化合一路本盘无（变节之合为卦体，非世应动化），不以合读翻成，注明。对象对齐：占婚者—妻财卯木（对方配偶位）与世应两家—应验落在婚事本身，同一。应期三步：月档尺度内取日点；冲实取子冲午（非用神），填实无空，逢值取卯日财值见破；取卯，舍冲实（不对位）。对表婚姻门：动空实空等条不合（用神静而不空），注明无对位条。R61二路复推：初推逢值卯，复推冲开取寅日异点，财破以值日见象为正，裁卯保留。',0.60)
B22['YM-020'] = ly('YM-020','方向：妻病凶危、终局不愈（单一终局：不愈）。具体断语：近段妻财子水巳月临绝、入癸未日墓（随墓），又逢兄弟辰土动而化午火回头生、忌神得生来克，病势入墓之象齐备；远段原神申金不现无生，救源不继，终局凶。应期双层：窗口为日档一旬内，主坐标子日（用神逢值而绝墓交集，危期）。置信：中高。','liuyao\n体系：六爻纳甲，占妻病以妻财为用神，本章为随墓章。盘面：巳建甲戌旬癸未日，空申酉；用神妻财子水两现，取应爻五爻子水与初爻动子水并参：子水巳月绝、未日为水之墓、初爻动化官鬼寅木化泄；兄弟辰土三爻动化父母午火回头生，忌神动克用神且得生；官鬼寅木世爻与上爻为病象，寅巳相刑。原神子孙申金不现且旬空，伏亦无力。动化方向：子水化寅木为化泄、辰土化午火为化回头生（生忌）；方向定性：忌化生扶为凶向加权；反转条件：源绝一路——原神不现旬空、无日月生扶（巳月癸未均不生金）、忌动克用，三项近齐，维持凶定性。原神存续判：无根无扶，判源绝（终局翻转仍以本盘用神绝墓自证，不单独凭源绝翻转）。对象对齐：所问对象寅命之妻—用神妻财子水—应验对象妻本人，同一；病占复述主语逐条为妻。应期三步：日档；冲实取巳冲亥（非用神），填实无空，逢值取子日；取子，舍冲实。对表疾病门：用神入墓绝无对位愈条，注明反面。R61二路复推：初推逢值子，复推冲墓取戌冲辰（忌墓）异点，用神危期以子日为正，裁子保留。病位依据链不全，不报病位。',0.70)
B22['YM-022'] = ly('YM-022','方向：身命多蹇、无大贵（单一终局：偏凶）。具体断语：戊午生人以午火为命元，世爻官鬼午火四爻子月休囚而动，化父母戌土泄气；上爻父母戌土动化妻财寅木又逢甲辰旬空，根基之文凭化空。一生官位起落、名位难固，须防子水冲午之年身体与职位同见波折。应期双层：窗口为年档，主坐标子年（水冲命元午火之年为限期关口）。置信：中低，身命长程盘面信息有限已降置信。','liuyao\n体系：六爻纳甲，身命占以世爻为主、复以生年午火为命元合参。盘面：丙戌年子建甲辰旬戊申日，空寅卯；世爻官鬼午火四爻，子月囚、动化父母戌土化泄，午戌半合收火入土；父母戌土上爻动化妻财寅木旬空；兄弟申金两现得申日。动化方向：午火化戌土为化泄、戌土化寅木为化生而化空；方向定性：世动化泄为退向，静态卦变艮六冲只调量级；反转条件：化泄非化绝，源绝一路不成立，只按退向定蹇、不直断大凶（量级收束）。对象对齐：戊午生人本人—世爻官鬼午火—应验落其本人身命，同一。对表寿元门：世休囚防冲克之年，与本断子年冲午同向，已查并取中。应期三步：年档；冲实取子年冲午，填实取寅年填空（化神），逢值取午年；寿元对表首选冲克之年，取子年，舍填实逢值（彼主文凭与命元值，不主限关）。R61二路复推：初推冲克子年，复推逢值午年异点，尺度同年档，对表首选裁子年保留。',0.50)
B22['YM-023'] = ly('YM-023','方向：有贵显之机、可得名位（单一终局：贵）。具体断语：官鬼寅木上爻应位临寅月建而旺，贵气有据；官鬼卯木二爻动化父母巳火，官动化文书，名位以文凭科名之途得之；量级止于中级显达，不至极贵——世爻兄弟丑土受寅卯木克，自身根基受压。应期双层：窗口为年档，主坐标寅年（官星寅木逢值临建之年）。置信：中。','liuyao\n体系：六爻纳甲，占贵以官鬼为用神。盘面：己丑年寅建甲子旬庚午日，空戌亥；用神官鬼两现，取上爻寅木临月建为主用，二爻卯木动化父母巳火为辅；父母巳火初爻动化兄弟未土，巳火得午日旺；世爻兄弟丑土三爻，寅月木克土。另卡面一处干支字形残损（父母巳火之干支在题面转录中有一字漫漶），据爻位表可复原为巳火，已据表落断并降少许置信。动化方向：卯木化巳火为化生（官化父）、巳火化未土为化泄；方向定性：官临建旺为吉底，官化父主名位凭文书得；反转条件：不成立。对象对齐：己巳生人本人—官鬼寅木—应验落其本人功名贵显，同一。应期三步：年档；冲实取申冲寅，填实无空，逢值取寅年；取逢值寅，舍冲实申（冲官为忌路）。对表：占贵对表无此门类，明写无表，按三步取点。R61二路复推：初推逢值寅年，复推化神巳年异点，官本爻值年优先，裁寅年保留。',0.55,trig(False,False,True,'卡面一处干支字形漫漶、据爻位表复原，读法留痕记 disputed 为 true；主用神未改取、无备用用神启用。'))
B22['YM-024'] = ly('YM-024','方向：天将放晴（单一终局：晴）。具体断语：父母巳火为晴象，两现而初爻巳火发动，云雨之父母动而化官鬼寅木，化神寅木非水，雨意不续；子孙酉金五爻持世逢卯日冲动，子孙主晴明，冲动则云开。应期双层：窗口为日档三日内，主坐标巳日（父母晴象逢值之日放晴）。置信：中。','liuyao\n体系：六爻纳甲，天时占晴以父母为云晴之象、子孙为晴明之神合参。盘面：午建甲申旬辛卯日，空午未；父母巳火上爻静、初爻应位动化官鬼寅木；子孙酉金五爻持世，午月金死而卯日冲酉为暗动；官鬼卯木二爻临日为阴雨之象当值即退。动化方向：巳火化寅木为化生；方向定性：晴象动化生扶不化水，雨势无续；反转条件：不成立。对象对齐：所问为天时晴—应验落在天气本身（非人对象面），同一。应期三步：日档；冲实无空（午未空为月日支非用神），填实取午日（空支），逢值取巳日；取巳，舍填实午（午为空支与晴象无涉）。对表：天时门类对表无此门类，明写无表。R61二路复推：初推逢值巳，复推冲世酉日异点同指云开，二路同向而坐标异，按晴象值日裁巳保留。',0.60)
B22['YM-025'] = ly('YM-025','方向：明日有雨（单一终局：雨）。具体断语：妻财酉金应爻临申月旺相，天时以财为雨象，财旺主雨；兄弟巳午火虽主晴热而午火旬空，晴神落空压不住旺财，明日乙卯日冲酉财动，雨落。应期双层：窗口为日档二日内，主坐标卯日（明日，冲动财爻之日应雨）。置信：中。','liuyao\n体系：六爻纳甲，天时占雨以妻财为雨象、子孙为晴象合参。盘面：申建甲寅旬甲寅日，空子丑，静卦旅且六合；用神妻财酉金上爻应位临月旺，妻财申金三爻同旺；子孙未土辰土两现静而生财（土生金反助雨象）；兄弟午火二爻旬空、巳火上邻静。动化方向：静卦无动化；反转条件：无动爻不成立。对象对齐：所问为明日天气—应验落在天气本身，同一。应期三步：日档（题面直问明日）；冲实取卯冲酉，填实取午日出空（晴神出空主转晴，与终局反向不取），逢值取酉日；取冲实卯（即明日），舍填实午（反向）、舍逢值酉（迟过所问）。对表：天时对表无此门类，明写无表。R61二路复推：初推冲实卯，复推逢值酉异点，所问明日尺度内只有卯，裁卯保留。粒度核：雨量级无双指针，只断有雨不报量级。',0.62)
B22['YM-027'] = ly('YM-027','方向：天将放晴、秋成偏歉（单一终局主断：晴）。具体断语：子孙申金三爻持世临甲申日动，主晴明发动；父母午火二爻动而旬空，雨云之象落空，午日出空填实则云散见日。秋成一面：官鬼卯木应爻为禾象，申日金克卯木、午月木休，禾苗受克，秋成止于中平偏歉。应期双层：窗口为日档一旬内，主坐标午日（父母午火填实出空、晴象定日）。置信：中。','liuyao\n体系：六爻纳甲，天时占晴以子孙为晴神、父母为云象，兼问秋成以官鬼卯木为禾象分断。盘面：庚辰年午建甲申旬甲申日，空午未；子孙申金三爻持世临日动化父母午火（化空、回头克而空），父母午火二爻动而空化兄弟辰土；官鬼卯木上爻应位，申日绝之。动化方向：申金化午火为化回头克而化神空、午火化辰土为化泄；方向定性：晴神临日动为吉底，化空只压应期；反转条件：化空一路部分成立（化神空而晴神临日有根），只降格迟晴，不反转。对象对齐：晴应落在天气、秋成应落在禾稼（题面对象面），分开断分开写，不合并。应期三步：日档；冲实取寅冲申（晴神），填实取午日填空，逢值取申日（已值）；对表无天时门；取填实午（云象空待实为晴之正机），舍冲实寅（冲晴神反动荡）、舍逢值申（占日已过此机制）。R61二路复推：初推填实午，复推冲实寅异点，闸门在空不在冲，裁午保留。粒度核：秋成量级指针一条（官木受克），只断偏歉等级带、不报成数。',0.55)
B22['YM-028'] = ly('YM-028','方向：可觅得葬地（单一终局：得地）。具体断语：父母未土初爻临丁未日值、父母戌土上爻应位两现，茔地之象落实；世爻妻财卯木三爻旬空，财空则议价未定之阻只是迟滞，地可成而价待谈。应期双层：窗口为日档一旬内，主坐标戌日（父母戌土逢值、与未土日值合成之地定期）。置信：中。','liuyao\n体系：六爻纳甲，茔葬觅地以父母为用神（茔地文书之象）。盘面：丁亥年寅建甲辰旬丁未日，空寅卯，静卦否而六合；用神父母两现：初爻未土临日、上爻戌土应位，寅月土休而得日值一爻有力；世爻妻财卯木三爻旬空，克父母而空克无力；官鬼两现为山向之气。动化方向：静卦无动化；反转条件：不成立。对象对齐：为父母觅地—用神父母爻在此指茔地文书面（题面对象为地），应验落在觅得之地本身，与占者父母之身分开写明，不混指。应期三步：日档；冲实取丑冲未，填实取卯日（世空填实主价定），逢值取戌日父值；取得地以父爻值为正，取戌，舍冲实丑（冲日值父反破）、舍填实卯（主价非主地）。对表：茔葬对表无此门类，明写无表。R61二路复推：初推逢值戌，复推冲实丑异点，父临日不宜冲，裁戌保留。',0.58)
B22['YM-029'] = ly('YM-029','方向：此地可用、可就地（单一终局：可用）。具体断语：兄弟戌土辰土两重临戌月旺相，地气厚重之象；世爻官鬼寅木二爻旬空，空主未定者只是手续人心未定，非地不可用；财子水应爻与初爻得月土克而弱，水口之气偏弱为唯一疵点，量级为止于可用、不称上佳吉地。应期双层：窗口为月档戌月内，主坐标辰日（冲动戌土、地气定局之日）。置信：中低，父母爻不现于六爻、文书一面无据已降置信。','liuyao\n体系：六爻纳甲，筮有地以父母为茔地用神，兼以兄弟土爻为地气。盘面：癸巳岁戌建甲辰旬癸丑日，空寅卯，静卦大畜；父母爻不现于六爻（卡面六爻表无父母），文书凭据一面无据不报；兄弟戌土四爻、辰土三爻临月旺；世爻官鬼寅木二爻旬空、戌月休囚；妻财子水应爻与初爻，丑日合子。动化方向：静卦无动化；反转条件：不成立。对象对齐：所问对象为此地—应验落在此地本身（非人对象），同一。应期三步：月档内取日点；冲实取辰冲戌，填实取寅日（世空填实），逢值取戌日；取冲实辰（动其旺土定局），舍填实寅（主世心定、次序在后）、舍逢值戌（占月已值无新机）。对表：茔葬对表无此门类，明写无表。R61二路复推：初推冲实辰，复推逢值戌异点，冲旺土为收藏定局之路，裁辰保留。粒度核：水口疵点指针一条（财水弱），只作量级带表述。',0.50)
B22['YM-030'] = ly('YM-030','方向：胎安（单一终局：安）。具体断语：子孙亥水四爻临辛亥日建而旺，胎元得日临值有力；初爻官鬼巳火动而冲亥，近段有惊动不安之象，然巳火动化妻财寅木、寅亥相合，冲后得合收束，惊动不伤胎本。应期双层：窗口为日档一旬内，主坐标寅日（化神寅木逢值、冲解合至之日胎象稳实）。置信：中。','liuyao\n体系：六爻纳甲，占孕胎安以子孙为胎元用神。盘面：申建甲辰旬辛亥日，空寅卯；用神子孙亥水四爻临日、得申月金生，旺相；官鬼巳火初爻动冲亥水，化妻财寅木，寅木空而与亥合；世爻父母未土上爻克水而月内土囚、克力有限。动化方向：巳火化寅木为化生且化合向；方向定性：冲胎之神动化合解，凶势自收，吉向定性；反转条件：不成立。对象对齐：孕妇之胎—子孙亥水—应验落在胎儿本身，孕妇为承受面，逐名复述为胎安，同一。应期三步：日档；冲实取巳（已冲在占日），填实取寅日化神填空，逢值取亥日（已值）；取填实寅（合解落地），舍逢值亥（占日已过）、舍冲实巳（冲为病象非安期）。对表产期门：本题问胎安非产期，对表无安胎门，明写无表。R61二路复推：初推填实寅，复推逢合寅同点（填实与逢合两机制同指寅），二路同点保留。',0.58)
B22['YM-032'] = ly('YM-032','方向：所怀为女（单一终局：女）。具体断语：子孙不现于六爻、伏藏受飞克，胎象偏阴弱；本卦归妹，世爻父母丑土为阴土持世，卦气从阴，断女。育养一面：子孙伏而受克，只主胎养须慎，不直断不育。应期：本题问性别无应期坐标可推，明写无应期、只断性别一面。置信：低，子孙伏藏、断性别依据单薄已显著降置信。','liuyao\n体系：六爻纳甲，占男女以子孙为胎元用神、兼以卦象阴阳为参。盘面：戌建甲子旬戊辰日，空戌亥，静卦归妹；子孙爻不现于卡面六爻表，伏藏之象（伏于何爻卡面未逐字标明，据兑宫例伏亥水受土飞克，只作伏弱一据，不臆断伏位细节）；父母戌土应爻旬空、父母丑土三爻持世；官鬼午火巳火两现。动化方向：静卦无动化；反转条件：不成立。对象对齐：孕妇之胎—伏子孙—性别应验落在胎儿本身，同一。应期：无应期断语，R61-REV1-2/-3 不适用，明写于此。粒度核：性别断项支撑指针为伏弱与卦阴两条同向，保留但置信低；育养断项指针不足，降格为须慎表述。',0.45)
B22['YM-033'] = ly('YM-033','方向：复卜得子之象成（单一终局：有子）。具体断语：子孙亥水四爻得甲申日金生、与卯月半合，原神有源；世爻官鬼巳火二爻与申日相合，嗣续之门已动。与初占无子之断相比，本卦子孙得生得合，象已转。应期双层：窗口为月档本年内，主坐标亥月（子孙亥水逢值之月，嗣音落地）。置信：中。','liuyao\n体系：六爻纳甲，求嗣以子孙为用神。盘面：丁亥年仲春卯建甲申旬甲申日，空午未，静卦萃；用神子孙亥水四爻，卯月木泄而得申日金生、亥卯半合；妻财卯木三爻临月为嗣续之媒；世爻官鬼巳火二爻，申日合巳、巳申合主门户相就；父母未土两现而休囚。动化方向：静卦无动化；反转条件：不成立；初占结论属题面事实，不作本卦改判之据，本卦自以子孙得生合立断。对象对齐：王氏本人之后嗣—子孙亥水—应验落在王氏子嗣一面，同一。应期三步：月档（嗣续非旦夕）；冲实取巳冲亥（冲用神不取），填实无空，逢值取亥月；取亥月，舍冲实巳（忌路）。对表：求嗣对表无此门类，明写无表。R61二路复推：初推逢值亥月，复推逢合取卯月异点，值月为子孙本气之期优先，裁亥月保留。',0.58)
B22['YM-034'] = ly('YM-034','方向：痘将发（单一终局：发）。具体断语：官鬼卯木二爻应位临乙卯日动，痘病之根临日发动；官动化兄弟丑土旬空，毒气化向空处，发而势有出路。子孙申金五爻持世，痘后调治之神在位，发痘过程可过，程度中平。应期双层：窗口为日档一旬内，主坐标丑日（官鬼化神丑土填实出空之日，痘点见形）。置信：中。','liuyao\n体系：六爻纳甲，占有花以官鬼为痘病之象、子孙为痘儿本体与调治合参。盘面：丑建甲寅旬乙卯日，空子丑；官鬼卯木二爻应位临日动，化兄弟丑土旬空；兄弟丑土三爻动化妻财亥水；子孙申金五爻持世，丑月土生金。动化方向：卯木化丑土为化泄而化空、丑土化亥水为化泄；方向定性：病根动而化空泄，发象成立而毒势有泄路；反转条件：不成立。对象对齐：孩童本人—官鬼为其痘病、子孙为其本体—应验落在该孩童身上，逐名复述为此孩童，同一。应期三步：日档；冲实取酉冲卯，填实取丑日化神填空，逢值取卯日（占日已值）；取填实丑（痘形以化神实而见），舍冲实酉（冲病根主散而非见形）、舍逢值卯（已过）。对表：痘疹对表无此门类，明写无表。R61二路复推：初推填实丑，复推逢值卯异点，见形取化神实日，裁丑保留。',0.60)
B22['YM-035'] = ly('YM-035','方向：痘将发而轻（单一终局：发而可过）。具体断语：子孙申金五爻持世发动，化兄弟未土回头生，本体之神动而得生，痘虽发而根基自固；官鬼卯木二爻应位临乙卯日为痘根当值，发点在近。程度较同日他例为轻，过程可过。应期双层：窗口为日档一旬内，主坐标未日（世爻化神未土逢值回生落地、痘发见形之日）。置信：中。','liuyao\n体系：六爻纳甲，占有花以子孙为本体用神、官鬼为痘病之象。盘面：丑建甲寅旬乙卯日，空子丑，与前例同日另占；用神子孙申金五爻持世动，化兄弟未土回头生；官鬼卯木二爻应位临日静；父母午火四爻、巳火初爻为火毒之参。动化方向：申金化未土为化回头生；方向定性：用神化回头生为吉向定性优先，静态官临日只主发痘之期不压本体；反转条件：源绝三征与化绝一路均不成立。对象对齐：另一孩童本人—子孙申金世—应验落在此孩童身上，与前例孩童分开写明，不混指。应期三步：日档；冲实取寅冲申，填实无空（未非空），逢值取未日化神值；取未，舍冲实寅（冲世本体不利）。对表：痘疹对表无此门类，明写无表。R61二路复推：初推逢值未，复推回头生以丑日（未之原神土值）异点，化神值日更直，裁未保留。',0.55)
B22['YM-037'] = ly('YM-037','方向：子痘凶险、终局难愈（单一终局：难愈）。具体断语：近段子孙寅木三爻持世而旬空，痘儿本体落空；父母申金四爻动而冲克寅木，克身之手已动。远段申金化兄弟亥水、亥寅相合一线为解，然合神亥水无月日旺气，只够减轻、不够挽空克之局，终局偏凶。应期双层：窗口为日档一旬内，主坐标寅日（子孙出空逢值之日，吉凶见分晓、危象最显）。置信：中低。','liuyao\n体系：六爻纳甲，占子痘以子孙为本体用神、官鬼为痘病。盘面：未建甲辰旬甲辰日，空寅卯；用神子孙寅木三爻持世旬空，未月木囚、辰日土克；父母申金四爻动冲克寅木，化兄弟亥水；官鬼辰土三爻动、戌土五爻应位为痘病两重；妻财不现，生子孙之原神缺位。动化方向：申金化亥水为化泄、辰土化亥水为化泄；方向定性：克用之申动化泄且化亥合寅，克力后段自减，故近凶远减；反转条件：源绝查——原神妻财不现，无从言根，子孙本体空而受冲克，终局以本体状态自定凶，不凭源绝翻转。对象对齐：所问对象占者之子—子孙寅木世—应验落在子本人，病占复述主语逐条为子，同一。应期三步：日档；冲实取巳冲亥（解神），填实取寅日出空，逢值同寅日；取寅，舍冲实巳（解在后段）。对表疾病门：痘属疾病旁参，用神空无愈条对位，注明。R61二路复推：初推填实寅，复推逢值寅，二路同点保留。病位依据链不全，不报病位。',0.52)
B22['YM-038'] = ly('YM-038','方向：子病可愈（单一终局：愈）。具体断语：子孙戌土上爻应位临戌月建而旺，又有子孙丑土二爻同气，嗣体之神两重旺相，足以制官鬼亥水之病；官鬼亥水三爻持世，戌月辰日两重土克，病气受制。近段病在身上缠绵数日，远段随子孙旺气渐退。应期双层：窗口为日档一旬内，主坐标戌日（子孙逢值临建之日，病退见分晓）。置信：中高。','liuyao\n体系：六爻纳甲，占子病以子孙为本体用神、官鬼为病。盘面：戌建甲辰旬甲辰日，空寅卯，静卦同人；用神子孙戌土上爻临月建，子孙丑土二爻助之；病象官鬼亥水三爻持世，月日土克而衰；父母卯木初爻旬空。原神妻财申金五爻，戌月土生金有气，生子孙之源在。动化方向：静卦无动化；反转条件：不成立。原神存续：申金得月土生，判有根，远段有续。对象对齐：己亥生之子—子孙戌土—应验落在子本人，病占复述主语逐条为子，同一。应期三步：日档；冲实取辰冲戌（占日已冲动），填实无空，逢值取戌日；取戌，舍冲实辰（已过且冲用神）。对表疾病门：用神旺静无空破对位愈条，注明按三步取点。R61二路复推：初推逢值戌，复推冲实辰异点，用神临建以值日为正，裁戌保留。',0.68)
B22['YM-039'] = ly('YM-039','方向：妻病凶、终局不愈（单一终局：不愈）。具体断语：妻财酉金四爻逢卯月冲破，妻体之神月破无力；官鬼亥水三爻应位得卯月木生、壬子日临旺，病气方盛而克泄妻财；子孙未丑土两现而卯月受克，制病之药无力。近段病势即重，远段破象无救，终局凶。应期双层：窗口为日档一旬内，主坐标酉日（妻财逢值实破之日，危期见分晓）。置信：中高。','liuyao\n体系：六爻纳甲，占妻病以妻财为用神。盘面：癸卯岁卯建甲辰旬壬子日，空寅卯，静卦离而六冲；用神妻财酉金四爻，卯月冲破、金囚；病象官鬼亥水三爻应位，月生日至，旺相；子孙未土五爻、丑土二爻，卯月木克土；世爻兄弟巳火上爻。动化方向：静卦无动化；反转条件：无动爻不成立。破象过表：酉金无日月生扶（卯月子日皆不生金）、逢值待实一路尚存，故断不愈之终局而量级止于病凶、不另报死期日辰。原神存续：子孙土受月克，判源减；终局以用神月破加病旺自定，不凭源绝翻转。对象对齐：程良玉之妻—妻财酉金—应验落在妻本人，病占复述主语逐条为妻，不回收到占者本人。应期三步：日档；冲实无（已破），填实取酉日实破，逢值同酉日；取酉。对表疾病门：月破而旺者实破愈——本用神破而不旺，反面成立，注明查表。R61二路复推：初推填实酉，复推逢值酉，二路同点保留。病位依据链不全，不报病位。',0.65)
B22['YM-040'] = ly('YM-040','方向：夫病可愈（单一终局：愈）。具体断语：近段官鬼亥水三爻持世为夫体，未月辰土之气压水、寅日亥寅合木泄水，病势缠重；转机在子孙戌土上爻应位动而化兄弟子水——子孙动主医药见效，化出子水与亥水同气助夫体，远段渐安。应期双层：窗口为日档一旬内，主坐标申日（兄弟申金为子水之源、申亥相生，药力得源之日见转机）。置信：中低，官鬼兼作夫体与病象两读已降置信。','liuyao\n体系：六爻纳甲，占夫病以官鬼为夫体用神，官鬼兼病象，两读并记取舍：以世爻官鬼亥水为夫体主用，病势轻重别以子孙制化衡之。盘面：未建甲午旬壬寅日，空辰巳；用神官鬼亥水三爻持世，未月土克、寅日合泄；子孙戌土上爻应位动化兄弟子水；兄弟午火四爻动化妻财申金。动化方向：戌土化子水为化生助用、午火化申金为化泄；方向定性：子孙动化生夫体为吉向；反转条件：不成立。对象对齐：所问对象夫—官鬼亥水世—应验落在夫本人，病占复述主语逐条为夫，同一。应期三步：日档；冲实取巳冲亥，填实无空（辰巳空为日旬空支、涉化神申不涉），逢值取亥日；初以逢值亥为窗，复核化神源申金生水之路，取申日为转机点，舍逢值亥（值而受合泄、力分）、舍冲实巳（冲夫体不利）。对表疾病门：冲去克神一路，克神为土无单支可冲，注明无对位点。R61二路复推：初推逢值亥，复推化源申异点，按解法优先裁申，保留单点并留痕。',0.53,trig(False,False,True,'官鬼在本例兼夫体用神与病象两读，basis 已并记取舍，disputed 记 true；主用神未改取、无备用用神启用。'))
B22['YM-042'] = ly('YM-042','方向：妻病可愈（单一终局：愈）。具体断语：妻财午火不现，伏于三爻兄弟亥水之下，伏神午火临午月建而旺，伏而临建最易引出；飞神亥水午月囚、克火之力弱。子孙卯木初爻得寅日同气，生伏财之源在位。近段病象闭伏未显，远段伏财出则妻体渐复。应期双层：窗口为日档一旬内，主坐标午日（伏神妻财午火逢值临建而出之日）。置信：中。','liuyao\n体系：六爻纳甲，占妻病以妻财为用神。盘面：午建甲戌旬戊寅日，空申酉，静卦既济；妻财不现，依坎宫例伏于三爻兄弟亥水之下，伏神午火临月建；飞神亥水持世，午月囚；子孙卯木初爻为药，寅日卯木同气旺；官鬼戌丑土为病象，午月火生土而病借伏财之火转生，此点压量级。动化方向：静卦无动化；反转条件：伏神引拨四项——伏有气（临月建）成立、飞神囚弱成立、引拨路（伏临建逢值）成立、无破绝反证成立，四项全成立，与可愈初判同向，作同向佐证。对象对齐：所问对象妻—伏妻财午火—应验落在妻本人，病占复述主语逐条为妻，同一。应期三步：日档；冲实取巳冲飞亥，填实无空，逢值取午日伏值；取午，舍冲实巳（冲飞亦冲散伏气，次选留窗边）。对表疾病门：伏藏类无对位愈条，注明按飞伏法取点。R61二路复推：初推逢值午，复推冲飞巳异点，伏临建以逢值为正路，裁午保留。',0.55)
B22['YM-043'] = ly('YM-043','方向：父病凶险、终局难愈（单一终局：难愈）。具体断语：父母午火二爻动而化妻财亥水回头克，父体之神动而受化神克伤；原神官鬼寅木上爻持世而旬空，生父之源落空；子孙申金三爻应位临申日旺，药神虽旺却克去原神官木，救路被截。近段病势已重，远段回头克应期一到更险。应期双层：窗口为日档一旬内，主坐标亥日（化神亥水逢值、回头克落实之日）。置信：中。','liuyao\n体系：六爻纳甲，占父病以父母为用神。盘面：戌建甲辰旬戊申日，空寅卯；用神父母午火二爻动，戌月火入墓乡、动化妻财亥水回头克；原神官鬼寅木上爻持世旬空；子孙申金三爻应位临日旺；妻财子水五爻为化神之同气。动化方向：午火化亥水为化回头克；方向定性：用神动化回头克为凶向；反转条件：化回头克无解（亥水不空、申日不冲亥），维持凶定性。原神存续：官木空而受申金克，判源减近绝，终局以用神化克自定，不单独凭源绝翻转。对象对齐：所问对象父—父母午火—应验落在父本人，病占复述主语逐条为父，不回收到占者本人。应期三步：日档；冲实取巳冲亥（化神），填实取寅日原神出空，逢值取亥日化神值；终局为凶，取凶应之亥，舍填实寅（源出空只主救机、与终局反向）、舍冲实巳（冲化神反解克，非凶应点）。对表疾病门：无对位愈条，注明。R61二路复推：初推逢值亥，复推填实寅异点，按终局自洽裁亥保留。病位依据链不全，不报病位。',0.60)
